class HouseholdDashboard { HouseholdDashboard.fromJson(Map<String, dynamic> json) : accounts = List<Map<String, dynamic>>.from(json['accounts'] as List? ?? const []), totals = Map<String, dynamic>.from(json['totals'] as Map? ?? const {}); final List<Map<String, dynamic>> accounts; final Map<String, dynamic> totals; }
class NotificationPage { NotificationPage.fromJson(Map<String, dynamic> json) : items = List<Map<String, dynamic>>.from(json['items'] as List? ?? const []), unreadCount = (json['unreadCount'] as num? ?? 0).toInt(); final List<Map<String, dynamic>> items; final int unreadCount; }
